/**
 * `motionary/runtime/format-obj` (10.5) — Wavefront OBJ + MTL loader for
 * `motionary/runtime/gl` (own parser): `v` / `vt` / `vn`, faces with any
 * number of vertices (fan-triangulated) and negative indices, `o` / `g`
 * groups, `usemtl` material switches (one mesh per material), `s` ignored;
 * MTL `Kd`, `Ks` + `Ns` (→ roughness), `Ke`, `d` / `Tr` (opacity), `map_Kd`
 * (with options stripped), `illum` ignored. Missing normals are computed
 * (flat). Parsing is pure (SSR / workers); `loadObj()` fetches the OBJ, its
 * `mtllib` files and textures relative to the OBJ URL.
 */
import { RUNTIME_VERSION, type RuntimeModule } from './registry';
import { GlNode, standardMaterial, computeNormals, texture, type Geometry, type Material, type Mesh } from './gl';

export interface ObjMaterial {
  name: string;
  Kd: [number, number, number];
  Ks: [number, number, number];
  Ke: [number, number, number];
  Ns: number;
  d: number;
  map_Kd?: string;
}

export interface ObjGroup {
  name: string;
  material: string;
  geometry: Geometry;
}

export interface ObjData {
  groups: ObjGroup[];
  mtllibs: string[];
  /** Vertex count read (before de-indexing). */
  vertexCount: number;
  triangleCount: number;
}

const nums = (p: string[], from: number, n: number): number[] => Array.from({ length: n }, (_, i) => parseFloat(p[from + i]) || 0);

/** Parse OBJ text into groups (one geometry per object / group × material). */
export function parseObj(text: string): ObjData {
  const v: number[] = [], vt: number[] = [], vn: number[] = [];
  const mtllibs: string[] = [];
  const groups: ObjGroup[] = [];
  let cur: { name: string; material: string; p: number[]; n: number[]; t: number[]; hasN: boolean; hasT: boolean } | null = null;
  let obj = 'default', mat = '', tris = 0;
  const flush = () => {
    if (cur && cur.p.length) {
      const g: Geometry = { positions: new Float32Array(cur.p), uvs: cur.hasT ? new Float32Array(cur.t) : undefined };
      groups.push({ name: cur.name, material: cur.material, geometry: cur.hasN ? { ...g, normals: new Float32Array(cur.n) } : computeNormals(g) });
    }
    cur = null;
  };
  const start = () => {
    if (!cur || cur.name !== obj || cur.material !== mat) {
      flush();
      cur = { name: obj, material: mat, p: [], n: [], t: [], hasN: true, hasT: true };
    }
    return cur;
  };
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line[0] === '#') continue;
    const p = line.split(/\s+/);
    switch (p[0]) {
      case 'v': v.push(...nums(p, 1, 3)); break;
      case 'vt': vt.push(...nums(p, 1, 2)); break;
      case 'vn': vn.push(...nums(p, 1, 3)); break;
      case 'o': case 'g': flush(); obj = p.slice(1).join(' ') || 'default'; break;
      case 'usemtl': mat = p.slice(1).join(' '); break;
      case 'mtllib': mtllibs.push(...p.slice(1)); break;
      case 'f': {
        const c = start();
        const verts = p.slice(1).map((s) => {
          const [a, b, n] = s.split('/');
          const ix = (x: string | undefined, len: number) => (x ? (+x < 0 ? len + +x : +x - 1) : -1);
          return [ix(a, v.length / 3), ix(b, vt.length / 2), ix(n, vn.length / 3)];
        });
        for (let i = 1; i + 1 < verts.length; i++) {
          for (const k of [verts[0], verts[i], verts[i + 1]]) {
            c.p.push(v[k[0] * 3], v[k[0] * 3 + 1], v[k[0] * 3 + 2]);
            if (k[1] >= 0) c.t.push(vt[k[1] * 2], 1 - vt[k[1] * 2 + 1]);
            else {
              c.hasT = false;
              c.t.push(0, 0);
            }
            if (k[2] >= 0) c.n.push(vn[k[2] * 3], vn[k[2] * 3 + 1], vn[k[2] * 3 + 2]);
            else {
              c.hasN = false;
              c.n.push(0, 0, 1);
            }
          }
          tris++;
        }
        break;
      }
    }
  }
  flush();
  return { groups, mtllibs, vertexCount: v.length / 3, triangleCount: tris };
}

/** Parse MTL text. */
export function parseMtl(text: string): Record<string, ObjMaterial> {
  const out: Record<string, ObjMaterial> = {};
  let m: ObjMaterial | null = null;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line[0] === '#') continue;
    const p = line.split(/\s+/);
    const k = p[0];
    if (k === 'newmtl') {
      m = out[p.slice(1).join(' ')] = { name: p.slice(1).join(' '), Kd: [0.8, 0.8, 0.8], Ks: [0, 0, 0], Ke: [0, 0, 0], Ns: 10, d: 1 };
      continue;
    }
    if (!m) continue;
    if (k === 'Kd' || k === 'Ks' || k === 'Ke') m[k] = nums(p, 1, 3) as [number, number, number];
    else if (k === 'Ns') m.Ns = parseFloat(p[1]) || 0;
    else if (k === 'd') m.d = parseFloat(p[1]);
    else if (k === 'Tr') m.d = 1 - parseFloat(p[1]);
    else if (k === 'map_Kd') m.map_Kd = p[p.length - 1]; // options (-s, -o, -bm …) precede the file name
  }
  return out;
}

/** OBJ material → runtime/gl standard material (Ns 0–1000 → roughness). */
export function objMaterial(m?: ObjMaterial): Material {
  if (!m) return standardMaterial({ color: [0.8, 0.8, 0.8, 1] });
  const spec = Math.max(...m.Ks);
  return standardMaterial({ color: [m.Kd[0], m.Kd[1], m.Kd[2], m.d], roughness: Math.min(1, Math.max(0.05, 1 - Math.sqrt(Math.min(m.Ns, 1000) / 1000) * (spec > 0 ? 1 : 0.4))), metallic: 0, emissive: m.Ke, transparent: m.d < 1 });
}

/** Build a node tree (one child per OBJ object, one mesh per material). */
export function objToNode(data: ObjData, materials: Record<string, ObjMaterial> = {}, textures: Record<string, TexImageSource> = {}): GlNode {
  const root = new GlNode('obj');
  const byName = new Map<string, GlNode>();
  for (const g of data.groups) {
    let n = byName.get(g.name);
    if (!n) {
      n = new GlNode(g.name, []);
      byName.set(g.name, n);
      root.add(n);
    }
    const om = materials[g.material];
    const mat = objMaterial(om);
    if (om?.map_Kd && textures[om.map_Kd]) mat.map = texture(textures[om.map_Kd]);
    (n.mesh as Mesh[]).push({ geometry: g.geometry, material: mat });
  }
  return root;
}

/** Fetch an OBJ (+ its MTL files and diffuse textures, relative to the OBJ URL) and build a node. */
export async function loadObj(url: string): Promise<GlNode & { extras: { obj: ObjData; materials: Record<string, ObjMaterial> } }> {
  const get = async (u: string) => {
    const r = await fetch(u);
    if (!r.ok) throw new Error(`[motionary] format-obj: could not load ${u} (${r.status})`);
    return r;
  };
  const data = parseObj(await (await get(url)).text());
  const materials: Record<string, ObjMaterial> = {};
  for (const lib of data.mtllibs) Object.assign(materials, parseMtl(await (await get(new URL(lib, new URL(url, location.href)).href)).text()));
  const textures: Record<string, TexImageSource> = {};
  await Promise.all(Object.values(materials).filter((m) => m.map_Kd).map(async (m) => {
    const blob = await (await get(new URL(m.map_Kd!, new URL(url, location.href)).href)).blob();
    textures[m.map_Kd!] = await createImageBitmap(blob);
  }));
  const node = objToNode(data, materials, textures) as any;
  node.extras = { obj: data, materials };
  return node;
}

export interface FormatObjApi {
  parseObj: typeof parseObj;
  parseMtl: typeof parseMtl;
  objMaterial: typeof objMaterial;
  objToNode: typeof objToNode;
  loadObj: typeof loadObj;
}

/** The module object for `use(formatObj)` (needs `gl`). */
export const formatObj: RuntimeModule<FormatObjApi> = { id: 'format-obj', version: RUNTIME_VERSION, tier: 'advanced', requires: ['core', 'gl'], api: { parseObj, parseMtl, objMaterial, objToNode, loadObj } };
